{
  "message": "I can help with that. To proceed, I need a few details and clarifications, then I’ll show you a summary for confirmation before making any changes.",
  "required_information": [
    {
      "item": "user_id",
      "prompt": "Please provide your user ID."
    },
    {
      "item": "reservation_id",
      "prompt": "Please provide the reservation ID. If you don’t have it, I can look it up after you share your user ID."
    }
  ],
  "clarifications": [
    {
      "item": "passenger_update",
      "prompt": "When you say “change the passenger to myself,” is this a single-passenger reservation and you want to replace the existing passenger with your own details? If there are multiple passengers, which passenger(s) should be updated? Note: we can modify passenger details but cannot change the number of passengers.",
      "needed_fields_per_passenger": [
        "first_name",
        "last_name",
        "dob (YYYY-MM-DD)"
      ]
    },
    {
      "item": "baggage",
      "prompt": "By “add 3 checked bags,” do you mean add 3 bags total across the whole reservation (not per passenger), in addition to any bags already on the reservation?"
    },
    {
      "item": "cabin_change",
      "prompt": "Confirm you want to keep the same flights and change the cabin for the entire reservation to economy."
    },
    {
      "item": "payment_method",
      "prompt": "For any fare difference from the cabin change and any baggage fees, which stored payment method should we use (one credit card or one gift card on your profile)? If you’re not sure what’s on file, I can list your saved methods after you provide your user ID."
    }
  ],
  "note": "After you provide the information above, I will verify that no part of the trip has already been flown, calculate baggage allowances based on your membership level and cabin, determine any price difference, and present a detailed summary for your confirmation before applying any changes."
}

